from report_content import SECTIONS, section

TIMEOUT_ROWS = [
('DB','connect_timeout','MySQL参考10秒。AWS値はengine-default','10秒','10秒','10秒','初回ハンドシェイクのDB側待ち。JDBC TCP接続の期限ではない。','S53'),
('DB','wait_timeout','MySQL参考28800秒','600秒','3600秒','28800秒を維持','非対話セッションの無通信時間。実行中SQLを止める値ではない。Proxyが保持するDB接続を短時間で切らない。','S53 S07'),
('DB','interactive_timeout','MySQL参考28800秒','600秒','3600秒','28800秒を維持','Connector/J interactiveClient=falseが既定のため通常はこちらではなくwait_timeout。管理端末は個別の短い期限を検討。','S27 S53'),
('DB','innodb_lock_wait_timeout','MySQL参考50秒','5秒','30秒','5秒','InnoDB行ロックの待ち。共有DBでは短い値とバッチ分割を優先。デッドロック検出やmetadata lockとは別。','S54'),
('DB','lock_wait_timeout','MySQL参考31536000秒','10秒','30秒','10秒','DDLなどのメタデータロック待ち。DDLバッチだけ別セッションの保守期限を検討。長い既定値の放置を避ける。','S53'),
('DB','max_execution_time','MySQL参考0ms＝上限なし','5000ms','90000ms','90000ms + onlineのSELECTに5000msヒント','主に読取専用SELECTの上限。INSERT/UPDATE/DELETE全体やストアド内処理の万能タイマーではない。','S53'),
('DB','innodb_rollback_on_timeout','MySQL参考OFF','ON（要回帰）','ON（要回帰）','ON（要回帰）','行ロックタイムアウト時の部分成功を避ける。staticなので再起動。アプリ側rollback・接続廃棄の責任も残る。','S54'),
('DB','net_read_timeout','MySQL参考30秒','30秒','30秒、実測で60秒を検討','30秒','DBがクライアントからデータを受け取る途中の待ち。SQLの計算時間と関係を混同しない。','S53'),
('DB','net_write_timeout','MySQL参考60秒','60秒','60秒、遅い消費を改善','60秒','DBが結果をクライアントへ送る途中の待ち。大量一括取得の代わりにページング・チャンクを使う。','S53'),
('DB','aurora_transaction_timeout','8.4.8以降専用','8.4.7では不可','8.4.7では不可','8.4.7では不可','一覧に見えてもMinimumEngineVersionで除外。8.4.7のトランザクション期限はJTA/アプリ側で設計する。','S56 S57'),
('Proxy','ConnectionBorrowTimeout','120秒','直結では該当なし','直結では該当なし','3秒','接続不足やWriter切替中の待ち。バッチSQLを3秒で止める設定ではない。','S06 S07'),
('Proxy','IdleClientTimeout','1800秒','該当なし','該当なし','1800秒','アプリ側idle300秒を先にする。DB側wait_timeoutとの接続区間の違いに注意。','S07'),
('EAP','blocking-timeout-wait-millis','モデル/明示設定を確認','1000ms','DriverManagerではプールなし','online=1000ms','ローカルプールの借用待ち。新規物理接続の全時間を制限できない。別途JDBC connectTimeoutが必要。','S25'),
('JDBC','connectTimeout','0ms＝無期限','3000ms','5000ms','online=3000ms / batch=5000ms','TCP接続確立。SSM取得、DNS、全SQL、業務処理をまとめて制限するものではない。','S28'),
('JDBC','socketTimeout','0ms＝無期限','12000ms','150000ms','online=12000ms / batch=150000ms','ソケットの通信待ち上限。DBのSQL中断が即時に完了した保証にはしない。HTTP中断後のDB処理残留も検査する。','S28'),
('JDBC/EAP','query-timeout / setQueryTimeout','未指定0＝制限なしが基準','8秒','120秒','online=8秒 / batch=120秒','SQLごとのタイムアウト。単位は秒。ResultSetの全消費時間や複数SQLの総時間は別に管理。','S25 S29'),
('EAP','set-tx-query-timeout','実機モデルを確認','falseを明示','該当なし','online=falseを基準','trueは残りJTA時間をstatement期限に使うため、query-timeout=8との単純なmin動作と断定しない。基準設計は固定8秒とJTA20秒を別々に管理。','S25'),
('EAP/JTA','default-timeout','300秒','20秒','直接JDBCにはJTAなし','online=20秒','全トランザクションの期限。CMT/BMTと他の資源も含む。timeoutでマークされてもDB処理が瞬時に消えるとは限らない。','S25'),
('EAP pool','idle-timeout-minutes','実機モデルを確認','5分','DriverManagerではなし','online=5分','未使用の物理接続を閉じる。プール上限と最小値0、計画的な更新も合わせて24時間のProxy寿命に備える。','S07 S25'),
('アプリ','オンライン要求全体','業務仕様による','30秒','該当なし','30秒','接続待ち・SQL・整形・応答の合計。1SQLの8秒を何回でも使える設計にしない。残り期限を引き継ぐ。','設計提案'),
('バッチ','チャンク/ジョブ全体','業務仕様による','該当なし','180秒 / 仮60分','180秒 / 仮60分','1ジョブを1トランザクションにしない。中断後に確定済みチャンクから再開し、ジョブの許容時間を処理量で決める。','設計提案'),
('再試行','回数とバックオフ','製品間で異なる','原則1要求内0回、冪等時のみ期限内再試行','1チャンク最大3回、1/2/4秒+jitter','onlineは予算内、batchは最大3回','認証失敗・SQL誤りを再試行しない。COMMIT結果不明は業務IDで照合。障害時の連続再接続を防ぐ。','設計提案'),
]

SECTIONS.append(dict(sheet='10_タイムアウト',title='タイムアウトの既定値と用途別推奨：区間・単位・効き方を分ける',
 intro='数値はSLO未確定時の初期案。online: SELECT 5秒 → JDBC 8秒 → socket 12秒 → JTA 20秒 → 業務30秒。各タイマーは開始点と対象が異なり、単に数値の大小だけで整合性を証明できない。',
 headers=['層','パラメータ','デフォルトの根拠','オンライン直結','バッチ直結','共用Proxy経由','意味と注意点','根拠'],rows=TIMEOUT_ROWS))

JDBC_ROWS = [
('ドライバ','com.mysql.cj.jdbc.Driver','MySQL Connector/J','online/batch共通','旧com.mysql.jdbc.Driverを新規採用しない。JNDIは接続管理を抽象化するが、実際のMySQL通信はドライバが行う。','S24'),
('版選択','EAP 8.1検証組合せ','MySQL 8.4.5 / Connector/J 9.4.0を公式表で確認','この組合せを比較基準に、保守対象の修正版を固定','Aurora8.4.7+Proxyが同じ認定組合せであると断定しない。ドライバの現在最新版とRed Hat検証版は別。採用JAR/JDK/EAPパッチを固定し相互接続試験。','S26 S27'),
('TLS','sslMode','PREFERRED','VERIFY_IDENTITY','PREFERREDは暗号化も本人確認も必須にしない。実際のProxy FQDNをURLに指定する。','S27 S30'),
('TLS','tlsVersions','JDK/ドライバ依存','TLSv1.2,TLSv1.3','古いTLSを明示的に候補から外す。ProxyとDBで使う暗号スイートの共通集合を維持する。','S10 S30'),
('認証','allowPublicKeyRetrieval','false','false','検証付きTLSを使う構成で、公開鍵を無条件取得する緩和設定は不要。認証エラーをtrueで隠さない。','S27 S30'),
('文字','characterEncoding','未指定','UTF-8','Connector/J側のJava文字コード名。DBはutf8mb4。絵文字・異体字・サロゲートペアを試験する。','S27'),
('文字','connectionCollation','未指定','新規はutf8mb4_0900_ai_ciを候補','業務コードの大小文字やアクセントの区別は列単位で明示。既存照合順序を変更すると一意性や並びが変わるため移行試験が必要。','S27 S53'),
('時刻','connectionTimeZone','LOCAL','UTC','DB time_zone=UTCと併用。TIMESTAMPとDATETIMEの意味を分け、日本向け画面表示でAsia/Tokyoへ変換する。','S27'),
('時刻','forceConnectionTimeZoneToSession','false','falseを基準','DB共通UTCなら接続ごとのSETを増やさない。DB設定が異なる環境では明示的なsession設定を行い、Proxyへの影響を評価する。','S27 S09'),
('復旧','autoReconnect','false','false','失われたトランザクションやセッション状態を透過復元できない。壊れた接続はプールが捨て、業務単位で再実行判断する。','S27'),
('SQL安全','allowMultiQueries','false','false','SQL文字列連結を許す方向でバッチ化しない。PreparedStatementとaddBatch/executeBatchを使用する。','S27'),
('ローカルファイル','allowLoadLocalInfile','false','false','DB local_infile=0とも整合。必要な取込は専用ユーザー・専用経路で個別設計する。','S27'),
('prepared statement','useServerPrepStmts','false','online=false、batch=falseを基準','JDBC PreparedStatement自体は使い続ける。サーバーpreparedはProxyピン留めを招くため、必要性を測定して有効化する。','S09 S27'),
('prepared statement','cachePrepStmts','false','online=true/キャッシュ100程度を試験、batchは既定開始','パース等の再利用。EAPのprepared-statement-cache-sizeと二重に大きくしない。メモリ増加とSQL種類数を測定する。','S27 S25'),
('大量取得','useCursorFetch','false','基準false','trueにするとサーバーpreparedを使い、ピン留めやカーソル時間の影響が出る。大きい全件一括取得よりキー範囲ページングを先に検討する。','S09 S27'),
('バッチ送信','rewriteBatchedStatements','false','false開始、計測後に必要時true','巨大な一括SQLは16KB超のピン留めやpacket上限を招く。1回100～1000行は仮の開始値で、行サイズとロック時間で上限を決める。','S09 S27'),
('バッチ失敗','continueBatchOnError','true','batch=false','途中失敗後にどこまで実行したかを扱いやすくする。自動commitは止め、1チャンクをrollbackできる設計にする。','S29'),
('中断','queryTimeoutKillsConnection','false','trueを候補に実機試験','query timeout時に接続を破棄する方式。別接続からのKILLだけに依存しない。DB側SQLの停止・ロールバック完了までを負荷試験で観測する。','S29'),
('健全性','validate-on-match / background-validation','EAPモデルで確認','true / false','貸出時に検証。両方を有効にして重複検証を増やさない。検証直後の障害は防げないため実SQLの例外も処理する。','S24 S25'),
('健全性','ValidConnectionChecker / ExceptionSorter','未設定の場合は個別追加','MySQLValidConnectionChecker / MySQLExceptionSorter','EAP公式MySQL例の拡張クラスを採用。例外の種類に応じて壊れた物理接続をプールから除去する。','S24'),
('EAPプール','min-pool-size / max-pool-size','EAPモデルで確認','0 / 20を初期案、prefill=false','最大コンテナ数とデプロイ中の新旧重複を掛けた合計を計算する。Proxyがあるから各Pod数百本にする設計は採らない。','S07 設計提案'),
('バッチ接続','DriverManagerから直接ドライバ使用','アプリの実装による','最大8 worker、各workerで1接続/チャンク','Proxy経由でもAPIはDriverManagerでよい。DriverManager自体にプールはない。try-with-resourcesで閉じ、全行ごとに接続作成しない。','S27 設計提案'),
('トランザクション','online JTA / batch local transaction','autocommitは通常true','onlineはコンテナ管理、batchは明示開始・commit・rollback','CMT内で勝手にConnection.commit()しない。複数DBやJMSの原子性が必要ならXA等の別設計が必要で、非XAのまま原子性を約束しない。','S24 S25'),
]
